{
  "name": "BuzzSync",
  "description": "An iOS-styled group notification app. Create groups, invite friends, and send instant alerts or AI-powered smart messages to everyone in the group.",
  "requestFramePermissions": [
    "microphone"
  ]
}

export interface User {
  id: string;
  name: string;
  avatarColor: string;
}

export interface Notification {
  id: string;
  senderName: string;
  senderId: string;
  message: string;
  timestamp: number;
  type: 'buzz' | 'message' | 'system';
}

export interface Group {
  id: string;
  name: string;
  code: string;
  members: User[];
  history: Notification[];
}

export enum AppView {
  ONBOARDING = 'ONBOARDING',
  HOME = 'HOME',
  GROUP = 'GROUP',
}

export enum NotificationPriority {
  NORMAL = 'NORMAL',
  URGENT = 'URGENT',
}

import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const generateSmartMessage = async (context: string, senderName: string): Promise<string> => {
  if (!apiKey) {
    console.warn("No API Key provided, returning fallback.");
    return `Hey everyone, ${context}!`;
  }

  try {
    const model = 'gemini-3-flash-preview';
    const prompt = `
      You are an assistant for a group notification app. 
      User "${senderName}" wants to send a notification to their group.
      Context/Intent: "${context}".

      Task: Generate a short, punchy, and engaging notification message (max 12 words). 
      If the context implies urgency, make it urgent. If it's fun, make it fun.
      Do not use quotes in the output. Just the message.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    return response.text?.trim() || context;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return context; // Fallback to original text on error
  }
};

import { Group, Notification, User } from "../types";
import { COLORS } from "../constants";

// In-memory store
let groups: Group[] = [];

export const createGroup = (name: string, creator: User): Group => {
  const code = Math.floor(1000 + Math.random() * 9000).toString();
  const newGroup: Group = {
    id: crypto.randomUUID(),
    name,
    code,
    members: [creator],
    history: [],
  };
  groups.push(newGroup);
  return newGroup;
};

export const joinGroup = (code: string, user: User): Group | null => {
  const group = groups.find((g) => g.code === code);
  if (group) {
    if (!group.members.find((m) => m.id === user.id)) {
      group.members.push(user);
    }
    return group;
  }
  return null;
};

export const getGroup = (groupId: string): Group | undefined => {
  return groups.find((g) => g.id === groupId);
};

export const sendNotification = (groupId: string, notification: Notification): boolean => {
  const group = groups.find((g) => g.id === groupId);
  if (group) {
    group.history.unshift(notification);
    // Keep history manageable
    if (group.history.length > 50) group.history.pop();
    return true;
  }
  return false;
};

// --- Simulation Logic ---

const MOCK_MESSAGES = [
  "Where is everyone?",
  "Meeting starts in 5!",
  "Anyone want coffee?",
  "Check the doc I sent.",
  "Buzzzz! 🐝",
];

const MOCK_NAMES = ["Alice", "Bob", "Charlie", "Diana"];

export const simulateIncomingNotification = (
  groupId: string, 
  currentUserIsSender: boolean,
  callback: (n: Notification) => void
) => {
  if (currentUserIsSender) return;

  const group = getGroup(groupId);
  if (!group) return;

  // 30% chance a fake user sends a message if the group has < 2 members (to make it feel alive)
  if (Math.random() > 0.7 || group.members.length < 2) {
    const randomName = MOCK_NAMES[Math.floor(Math.random() * MOCK_NAMES.length)];
    const message = MOCK_MESSAGES[Math.floor(Math.random() * MOCK_MESSAGES.length)];

    const notif: Notification = {
      id: crypto.randomUUID(),
      senderName: randomName,
      senderId: 'mock-user',
      message: message,
      timestamp: Date.now(),
      type: Math.random() > 0.5 ? 'buzz' : 'message',
    };

    // Add to state
    sendNotification(groupId, notif);

    // Trigger callback
    callback(notif);
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "font-semibold rounded-xl transition-all active:scale-95 disabled:opacity-50 disabled:active:scale-100 flex items-center justify-center gap-2";
  const sizeStyles = "px-4 py-3.5 text-[17px]"; // iOS standard tap target sizeish

  let variantStyles = "";
  switch (variant) {
    case 'primary':
      variantStyles = "bg-blue-600 text-white shadow-sm hover:bg-blue-700";
      break;
    case 'secondary':
      variantStyles = "bg-gray-200 text-gray-900 hover:bg-gray-300";
      break;
    case 'danger':
      variantStyles = "bg-red-500 text-white hover:bg-red-600";
      break;
    case 'ghost':
      variantStyles = "bg-transparent text-blue-600 hover:bg-blue-50";
      break;
  }

  const widthStyles = fullWidth ? "w-full" : "";

  return (
    <button 
      className={`${baseStyles} ${sizeStyles} ${variantStyles} ${widthStyles} ${className}`} 
      {...props}
    >
      {children}
    </button>
  );
};

import React from 'react';

