  const handleJoinGroup = () => {
    if (!user || !joinCodeInput.trim()) return;
    const group = joinGroup(joinCodeInput.trim(), user);
    if (group) {
      setGroupsList((prev) => {
        if (prev.find(g => g.id === group.id)) return prev;
        return [...prev, group];
      });
      setCurrentGroup(group);
      setView(AppView.GROUP);
      setJoinCodeInput('');
    } else {
      alert("Invalid Code");
    }
  };

  const handleBuzz = (messageOverride?: string) => {
    if (!user || !currentGroup) return;

    const message = messageOverride || "Buzzed you! 🔔";

    const notif: Notification = {
      id: crypto.randomUUID(),
      senderName: user.name,
      senderId: user.id,
      message: message,
      timestamp: Date.now(),
      type: 'buzz',
    };

    sendNotification(currentGroup.id, notif);

    // Optimistic update
    setCurrentGroup((prev) => {
      if (!prev) return null;
      return {
        ...prev,
        history: [notif, ...prev.history]
