        {/* Mobile Access Section */}
        <div className="mb-8 border-b border-gray-100 pb-6">
          <h4 className="text-sm font-semibold text-gray-900 mb-3 flex items-center gap-2">
            <Smartphone className="w-4 h-4 text-purple-500" />
