            <div>
              <p className="text-sm font-medium text-gray-900">Background Alerts</p>
              <p className="text-xs text-gray-500">
                {permission === 'granted' ? 'You are set to receive alerts.' : 'Enable to receive alerts while locked.'}
              </p>
            </div>
            <Button 
              variant={permission === 'granted' ? 'secondary' : 'primary'}
